fn putd(o:[*]u8,p:usize,x:f64)void{const b=@as(u64,@bitCast(x));for(0..8)|k|o[p+k]=@truncate(b>>(8*k));}
export fn fuzzy_operations(v:[*]const i64,n:usize,o:[*]u8,cap:usize)i64{if(n!=8)return -1;const op=v[0];if(op<0 or op>3)return -1;for(1..8)|i|{if(v[i]<0 or v[i]>1000)return -1;}if(op==0){for(4..8)|i|{if(v[i]!=0)return -1;}}else if(op==1 or op==2){if(v[7]!=0)return -1;}else if(v[4]!=0 or v[5]!=0 or v[6]!=0 or !(v[1]<v[2] and v[2]<v[3]))return -1;const size:usize=if(op==3)8 else 24;if(cap<size)return -2;const a=@as(f64,@floatFromInt(v[1]))/1000.0;const b=@as(f64,@floatFromInt(v[2]))/1000.0;const c=@as(f64,@floatFromInt(v[3]))/1000.0;switch(op){0=>{putd(o,0,1.0-c);putd(o,8,1.0-a);putd(o,16,1.0-b);},1=>{putd(o,0,@max(a,@as(f64,@floatFromInt(v[4]))/1000.0));putd(o,8,@min(c,@as(f64,@floatFromInt(v[6]))/1000.0));putd(o,16,(b+@as(f64,@floatFromInt(v[5]))/1000.0)/2.0);},2=>{putd(o,0,@min(a,@as(f64,@floatFromInt(v[4]))/1000.0));putd(o,8,(b+@as(f64,@floatFromInt(v[5]))/1000.0)/2.0);putd(o,16,@max(c,@as(f64,@floatFromInt(v[6]))/1000.0));},else=>{const x=@as(f64,@floatFromInt(v[7]))/1000.0;const y=if(x<=a or x>=c)0.0 else if(x<=b)(x-a)/(b-a) else (c-x)/(c-b);putd(o,0,y);}}return @intCast(size);}
